WITH by_dimension AS (SELECT o.channel, a.status AS shipment_status, COUNT(*) AS num_rows, AVG(a.cost) AS avg_cost, GROUPING_ID() AS grouping_level FROM shipments a JOIN orders o ON a.order_id = o.id GROUP BY GROUPING SETS ((o.channel, a.status), (o.channel), ())) SELECT channel, shipment_status, num_rows, avg_cost, grouping_level, CASE WHEN channel RLIKE '^(mobile|web)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS channel_zone FROM by_dimension ORDER BY shipment_status DESC
